// --- VERSION 1.1.0 ---
// - Fix Trip Group duration and distance math to use averages instead of sums
// - Resolve bug where only one PID rendered on initial load
// - Fix X-axis cutoff issue by ensuring full duration coverage
// - UI Cleanup: Remove map overlay text, add list of specific logs with links

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useParams, Link } from 'react-router-dom';
import TripChart from '../charts/TripChart';
import TripMap from '../maps/TripMap';
import InfoBar from '../shared/InfoBar';
import { DEFAULT_WINDOW_SECONDS, getDefaultVisibleRange } from '../../utils/rangeUtils';
import { getPidColor } from '../../utils/colorUtils';

export default function TripGroupDetail() {
  const { groupId } = useParams();

  // State management
  const [groupData, setGroupData] = useState(null);
  const [visibleRange, setVisibleRange] = useState({ min: 0, max: 0 });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Initial selected PIDs - explicitly include multiple to fix the "one PID on load" issue
  const [selectedPIDs, setSelectedPIDs] = useState([
    'vehicle_speed',
    'engine_rpm',
    'none',
    'none',
    'none'
  ]);

  const chartColors = selectedPIDs.map((pid, idx) => getPidColor(pid, idx));

  const handlePIDChange = useCallback((index, value) => {
    setSelectedPIDs(prev => {
      const updated = [...prev];
      updated[index] = value;
      return updated;
    });
  }, []);

  const handleChartZoom = useCallback((newRange) => {
    setVisibleRange(newRange);
  }, []);

  // Prepare data for all logs in the group
  const comparisonData = useMemo(() => {
    if (!groupData?.logs || !groupData?.log_data) return null;

    return groupData.logs.map(log => ({
      id: log.log_id,
      name: `Trip ${log.log_id} (${new Date(log.start_timestamp * 1000).toLocaleDateString()})`,
      data: groupData.log_data[log.log_id] || [],
      columns: Object.keys(groupData.log_data[log.log_id]?.[0] || {})
    }));
  }, [groupData]);

  // Use the log with the most data points as the time reference to fix X-axis cutoff
  const referenceLog = useMemo(() => {
    if (!comparisonData || comparisonData.length === 0) return null;
    return [...comparisonData].sort((a, b) => b.data.length - a.data.length)[0];
  }, [comparisonData]);

  const tripInfo = useMemo(() => {
    if (!groupData?.logs || groupData.logs.length === 0) return null;

    const logs = groupData.logs;
    const count = logs.length;

    // MATHEMATICAL AVERAGES as requested
    const avgDistance = logs.reduce((sum, l) => sum + (parseFloat(l.distance_miles) || 0), 0) / count;
    const avgDuration = logs.reduce((sum, l) => sum + (parseFloat(l.trip_duration_seconds) || 0), 0) / count;

    let earliestStart = null;
    logs.forEach(log => {
      if (log.start_timestamp) {
        const startTime = new Date(log.start_timestamp * 1000);
        if (!earliestStart || startTime < earliestStart) earliestStart = startTime;
      }
    });

    return {
      file_name: `Group: ${groupId.substring(0, 8)}...`,
      start_time: earliestStart ? earliestStart.getTime() : null,
      trip_distance_miles: avgDistance,
      trip_duration_seconds: avgDuration,
      row_count: referenceLog?.data?.length || 0,
      trip_group_id: groupId
    };
  }, [groupData, groupId, referenceLog]);

  useEffect(() => {
    if (!groupId) return;
    setLoading(true);
    setError(null);

    const fetchGroupData = async () => {
      try {
        const response = await fetch(`/api/trip-groups/${groupId}`);
        if (!response.ok) throw new Error(`HTTP ${response.status}: ${response.statusText}`);
        const data = await response.json();

        if (!data.logs || data.logs.length === 0) {
          throw new Error('Invalid group data: missing or empty logs array');
        }

        setGroupData(data);

        // Find the longest log to set initial range to ensure we see the whole trip
        let maxLen = 0;
        let longestData = null;
        Object.values(data.log_data).forEach(d => {
          if (d.length > maxLen) {
            maxLen = d.length;
            longestData = d;
          }
        });

        if (longestData) {
          const initialRange = { min: 0, max: longestData.length - 1 };
          setVisibleRange(initialRange);
        }

      } catch (err) {
        console.error(`[TripGroupDetail] Error fetching group ${groupId}:`, err);
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchGroupData();
  }, [groupId]);

  if (loading) return <div className="p-8 text-center text-gray-400">Loading trip group data...</div>;
  if (error) return <div className="p-8 text-center text-red-400">Error: {error}</div>;
  if (!comparisonData || comparisonData.length === 0) return <div className="p-8 text-center text-gray-400">No data available</div>;

  return (
    <div className="space-y-4">
      <InfoBar tripInfo={tripInfo} groupLogs={groupData?.logs || []} />

      <TripChart
        log={referenceLog}
        logs={comparisonData} 
        selectedPIDs={selectedPIDs}
        onPIDChange={handlePIDChange}
        chartColors={chartColors}
        visibleRange={visibleRange}
        setVisibleRange={setVisibleRange}
        onChartZoom={handleChartZoom}
        mode="comparison"
      />

      <TripMap
        primaryPath={referenceLog?.data || []}
        secondaryPaths={comparisonData.filter(l => l.id !== referenceLog?.id).map(l => l.data)}
        columns={['latitude', 'longitude']}
        visibleRange={visibleRange}
        showDataPoints={true}
      />

      {/* Logs in this group list */}
      <div className="bg-gray-800 rounded-lg p-6 shadow-xl border border-gray-700">
        <h3 className="text-xl font-bold text-cyan-400 mb-4 flex items-center gap-2">
          <span>Logs in this Comparison Group</span>
          <span className="text-sm font-normal text-gray-500">({groupData.logs.length} trips)</span>
        </h3>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-gray-300">
            <thead className="text-xs uppercase text-gray-500 border-b border-gray-700">
              <tr>
                <th className="pb-2 font-medium">Log ID</th>
                <th className="pb-2 font-medium">Start Time</th>
                <th className="pb-2 font-medium">Distance</th>
                <th className="pb-2 font-medium">Duration</th>
                <th className="pb-2 font-medium text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-700/50">
              {groupData.logs.map(log => (
                <tr key={log.log_id} className="hover:bg-gray-700/30 transition-colors">
                  <td className="py-3 font-mono text-cyan-500/80">{log.log_id}</td>
                  <td className="py-3">{new Date(log.start_time).toLocaleString()}</td>
                  <td className="py-3">{(parseFloat(log.trip_distance_miles) || 0).toFixed(2)} mi</td>
                  <td className="py-3">
                    {Math.floor(log.trip_duration_seconds / 60)}m {Math.floor(log.trip_duration_seconds % 60)}s
                  </td>
                  <td className="py-3 text-right">
                    <Link 
                      to={`/logs/${log.log_id}`}
                      className="text-blue-400 hover:text-blue-300 underline underline-offset-4"
                    >
                      View Single Detail
                    </Link>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
